window.kbPageData["views/entry/k-4f46e00e7a11b601"] = {"key":"entry/k-4f46e00e7a11b601","state":{"route":"entry/k-4f46e00e7a11b601"},"node":{"id":"k-4f46e00e7a11b601","mode":"k","title":"青藏铁路冻土路基热棒","type":"原理与机制","domain":"地理","reading":"","intro":"","priority":100,"aliases":["青藏铁路热棒通过导出路基热量保护冻土层结构"],"qs":["江苏 2025 A类 行测#20"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"冻土路基热棒是一种密封的重力式热管，下部埋入土中吸热，上部露出地面散热。当外界气温低于埋地段周围土温时，热棒利用管内工质的蒸发和冷凝，将热量从土体传到空气中。","review":{"definition":"冻土路基热棒是一种密封的重力式热管，下部埋入土中吸热，上部露出地面散热。当外界气温低于埋地段周围土温时，热棒利用管内工质的蒸发和冷凝，将热量从土体传到空气中。","explanation":"青藏铁路安多试验段的热棒采用液氨作工质。管内液氨在下部吸热汽化，氨蒸气上升到地上冷凝段，向空气放热并凝成液体，再靠重力流回下部。原解析把上升的蒸气误写成了路基受热产生的水汽。题图中的金属管通过这一循环降低路基地温，减轻多年冻土融化引起的沉降，因此第20题选D“保护冻土层的结构”。","references":[{"source":"web-59a4b5ff76864bc5","location":"《岩土工程学报》2011年增刊1，第504页，第0节“引言”及第1节“试验工程概况”","quote":"热棒采用液氨－碳钢热棒"}],"evidence":"保护冻土层的结构","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2025 A类 行测#20":{"paper":"江苏 2025 A类 行测","n":20,"mod":"常识判断","src":["98687766ac277f427cd6.pdf",5],"asrc":["4fe8e0544dd7b47699d2.pdf",8],"card":"885e23a7e9386ffc962696cf","links":[{"id":"k-4f46e00e7a11b601","role":"直接考查","why":"热棒把路基中的热量释放到空气中，减轻冻土融化对土层结构的破坏。"}]}},"terms":{},"references":{"web-59a4b5ff76864bc5":{"name":"李永强《青藏铁路多年冻土区热棒直径对降温效果和产冷量的影响分析》","url":"https://cgejournal.com/cn/article/pdf/preview/14311.pdf#page=2"}},"topics":[],"units":{"k-4f46e00e7a11b601":[["江苏 2025 A类 行测#20"]]}};
